<?php
require_once __DIR__.'/learning.php';
function ls_dashboard(mysqli $db,array $a):array{
 $meetings=ac_rows($db,'SELECT m.* FROM lms_meetings m WHERE '.rs_meeting_filter($a));
 $tasks=ac_rows($db,'SELECT t.id,t.category FROM lms_tasks t JOIN lms_meetings m ON m.id=t.meeting_id WHERE '.rs_meeting_filter($a));
 $self=$a['role']==='peserta_intensif'?' AND a.siswa_id='.(int)$a['id']:'';
 $attendance=ac_rows($db,'SELECT a.*,m.meeting_date,m.title AS meeting_title FROM lms_attendance a JOIN lms_meetings m ON m.id=a.meeting_id WHERE '.rs_meeting_filter($a).$self);
 $subs=ls_submissions($db,$a);$today=date('Y-m-d');$start=(new DateTimeImmutable('monday this week'))->format('Y-m-d');$end=(new DateTimeImmutable($start))->modify('+6 days')->format('Y-m-d');
 $current=array_filter($attendance,fn($r)=>$r['meeting_date']===$today);$count=fn($statuses)=>count(array_filter($current,fn($r)=>in_array($r['status'],$statuses,true)));
 $done=count(array_unique(array_column($subs,'task_id')));$grades=array_values(array_map(fn($s)=>(float)$s['grade'],array_filter($subs,fn($s)=>$s['published_at']&&$s['grade']!==null&&is_numeric($s['grade']))));
 $past=array_filter($meetings,fn($m)=>$m['meeting_date']<=$today&&$m['type']!=='Libur');$pastIds=array_column($past,'id');$present=count(array_filter($attendance,fn($r)=>in_array($r['meeting_id'],$pastIds)&&in_array($r['status'],['hadir','terlambat'],true)));
 $activities=[];foreach(array_slice($subs,0,5)as $s)$activities[]=['title'=>$s['task_title'],'date'=>$s['submitted_at'],'date_label'=>date('d M Y H:i',strtotime($s['submitted_at'])),'status'=>$s['published_at']?'Nilai: '.$s['grade']:'Dikumpulkan','type'=>$s['published_at']?'tugas_dinilai':'tugas'];
 foreach(array_slice(array_reverse($attendance),0,5)as $r)$activities[]=['title'=>$r['meeting_title'],'date'=>$r['attended_at'],'date_label'=>date('d M Y H:i',strtotime($r['attended_at'])),'status'=>$r['status'],'type'=>'kehadiran'];usort($activities,fn($a,$b)=>strcmp($b['date'],$a['date']));
 $trend=[];$months=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Ags','Sep','Okt','Nov','Des'];$base=new DateTimeImmutable('first day of this month');for($i=5;$i>=0;$i--){$month=$base->modify("-$i months");$prefix=$month->format('Y-m');$trend[]=['name'=>$months[(int)$month->format('n')-1],'hadir'=>count(array_filter($attendance,fn($r)=>str_starts_with($r['meeting_date'],$prefix)&&in_array($r['status'],['hadir','terlambat'],true)))];}
 return ['total_siswa'=>count(rs_roster($db,$a)),'hadir_hari_ini'=>$count(['hadir']),'izin_hari_ini'=>$count(['izin','sakit']),'terlambat_hari_ini'=>$count(['terlambat']),'trend_kehadiran'=>$trend,'comparison'=>null,'comparison_label'=>'Belum ada data pembanding','total_tugas'=>count($tasks),'tugas_selesai'=>$done,'pending_assignments'=>max(0,count($tasks)-$done),'total_kehadiran'=>$present,'attendance_rate'=>count($past)?round($present/count($past)*100,1):null,'rata_rata_nilai'=>$grades?round(array_sum($grades)/count($grades),1):null,'materi_tersedia'=>count(array_filter($meetings,fn($m)=>$m['meeting_date']<=$today&&!empty($m['material_file']))),'materi_dipelajari'=>null,'classes_this_week'=>count(array_filter($meetings,fn($m)=>$m['meeting_date']>=$start&&$m['meeting_date']<=$end&&$m['type']!=='Libur')),'aktivitas_terakhir'=>array_slice($activities,0,5),'period'=>['from'=>$start,'to'=>$end,'timezone'=>'Asia/Jakarta']];
}
